=== FILE: apb_gpio.v ===
// apb_gpio: APB4 general-purpose I/O block with interrupts.
//
// Implements interface_spec.md (apb_gpio) following microarchitecture.md:
//   * zero wait states, pready tied high, completion strobe psel && penable;
//   * nine 32-bit registers, bits N and up held at zero by the PINS mask;
//   * byte-strobed writes, write-1-to-clear INTR_STATUS;
//   * rising/falling/high/low detection from two sample registers;
//   * a detection beats a clear of the same bit on the same edge;
//   * irq = |(INTR_STATUS & INTR_ENABLE).
// Reset: presetn, active low, synchronous.
`default_nettype none

module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output reg  [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

  // Bits 0 to N-1 set: the pins that exist.
  localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

  // Register indices, paddr[5:2].
  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // ---------------------------------------------------------------------
  // State
  // ---------------------------------------------------------------------
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] rise_en_q;
  reg [31:0] fall_en_q;
  reg [31:0] high_en_q;
  reg [31:0] low_en_q;
  reg [31:0] intr_en_q;
  reg [31:0] status_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;

  reg [31:0] data_out_d;
  reg [31:0] dir_d;
  reg [31:0] rise_en_d;
  reg [31:0] fall_en_d;
  reg [31:0] high_en_d;
  reg [31:0] low_en_d;
  reg [31:0] intr_en_d;
  reg [31:0] in_wide;

  // ---------------------------------------------------------------------
  // APB decode
  // ---------------------------------------------------------------------
  wire        access     = psel && penable;
  wire [3:0]  idx        = paddr[5:2];
  wire        upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire        mapped     = (paddr[1:0] == 2'b00) && upper_zero &&
                           (idx <= IDX_INTR_STATUS);
  wire        wr_en      = access && pwrite && mapped;
  wire        rd_en      = access && !pwrite && mapped;
  wire [31:0] wmask      = {{8{pstrb[3]}}, {8{pstrb[2]}},
                            {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  function [31:0] merge_w;
    input [31:0] old_v;
    input [31:0] new_v;
    input [31:0] m_v;
    begin
      merge_w = (old_v & ~m_v) | (new_v & m_v);
    end
  endfunction

  // ---------------------------------------------------------------------
  // Input sample, widened to 32 bits with zeros above N
  // ---------------------------------------------------------------------
  always @* begin
    in_wide          = 32'd0;
    in_wide[N-1:0]   = gpio_in;
  end

  // ---------------------------------------------------------------------
  // Detection and status
  // ---------------------------------------------------------------------
  wire [31:0] rise_ev  = in_q & ~in_prev_q;
  wire [31:0] fall_ev  = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise_ev & rise_en_q) | (fall_ev & fall_en_q) |
                          (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
  wire [31:0] clear_m  = (wr_en && (idx == IDX_INTR_STATUS)) ?
                         (pwdata & wmask) : 32'd0;
  // The OR with detected comes last: a detection beats a clear.
  wire [31:0] status_d = (status_q & ~clear_m) | detected;

  // ---------------------------------------------------------------------
  // Read/write register next state
  // ---------------------------------------------------------------------
  always @* begin
    data_out_d = data_out_q;
    dir_d      = dir_q;
    rise_en_d  = rise_en_q;
    fall_en_d  = fall_en_q;
    high_en_d  = high_en_q;
    low_en_d   = low_en_q;
    intr_en_d  = intr_en_q;
    if (wr_en) begin
      case (idx)
        IDX_DATA_OUT:    data_out_d = merge_w(data_out_q, pwdata, wmask);
        IDX_DIR:         dir_d      = merge_w(dir_q,      pwdata, wmask);
        IDX_INTR_RISE:   rise_en_d  = merge_w(rise_en_q,  pwdata, wmask);
        IDX_INTR_FALL:   fall_en_d  = merge_w(fall_en_q,  pwdata, wmask);
        IDX_INTR_HIGH:   high_en_d  = merge_w(high_en_q,  pwdata, wmask);
        IDX_INTR_LOW:    low_en_d   = merge_w(low_en_q,   pwdata, wmask);
        IDX_INTR_ENABLE: intr_en_d  = merge_w(intr_en_q,  pwdata, wmask);
        default: ;  // DATA_IN (error, no change), INTR_STATUS (via clear_m)
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // Register block: synchronous active-low reset, then q <= d
  // ---------------------------------------------------------------------
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'd0;
      dir_q      <= 32'd0;
      rise_en_q  <= 32'd0;
      fall_en_q  <= 32'd0;
      high_en_q  <= 32'd0;
      low_en_q   <= 32'd0;
      intr_en_q  <= 32'd0;
      status_q   <= 32'd0;
      in_q       <= 32'd0;
      in_prev_q  <= 32'd0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      intr_en_q  <= intr_en_d;
      status_q   <= status_d;
      in_q       <= in_wide;
      in_prev_q  <= in_q;
    end
  end

  // ---------------------------------------------------------------------
  // Read data: zero unless a mapped read access
  // ---------------------------------------------------------------------
  always @* begin
    prdata = 32'd0;
    if (rd_en) begin
      case (idx)
        IDX_DATA_OUT:    prdata = data_out_q;
        IDX_DIR:         prdata = dir_q;
        IDX_DATA_IN:     prdata = in_q;
        IDX_INTR_RISE:   prdata = rise_en_q;
        IDX_INTR_FALL:   prdata = fall_en_q;
        IDX_INTR_HIGH:   prdata = high_en_q;
        IDX_INTR_LOW:    prdata = low_en_q;
        IDX_INTR_ENABLE: prdata = intr_en_q;
        IDX_INTR_STATUS: prdata = status_q;
        default:         prdata = 32'd0;
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // Outputs
  // ---------------------------------------------------------------------
  assign pready   = 1'b1;
  assign pslverr  = access && (!mapped || (pwrite && (idx == IDX_DATA_IN)));
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & intr_en_q);

`ifdef FORMAL
  // Design-intent assertions (protocol responses); not a proof setup.
  always @(*) begin
    assert (pready == 1'b1);
    if (!access) begin
      assert (prdata == 32'd0);
      assert (pslverr == 1'b0);
    end
    if (pslverr) begin
      assert (prdata == 32'd0);
    end
    assert ((detected & ~PINS) == 32'd0);
    assert (irq == |(status_q & intr_en_q));
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
// apb_gpio_tb: self-checking testbench for apb_gpio (interface_spec.md).
//
// The stimulus changes on the falling edge of pclk. Each check is reported
// with $error on failure and counted on success. A cycle-level reference
// model, written bit by bit from the specification, is compared with the
// DUT outputs on every cycle and with every read. Hand-computed expected
// values back the directed checks. Intended for N = 8 and N = 32 (N >= 7).
`timescale 1ns/1ps
`default_nettype none

module apb_gpio_tb;

  parameter integer N = 8;
  localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

  localparam [7:0] A_DATA_OUT = 8'h00;
  localparam [7:0] A_DIR      = 8'h04;
  localparam [7:0] A_DATA_IN  = 8'h08;
  localparam [7:0] A_RISE     = 8'h0C;
  localparam [7:0] A_FALL     = 8'h10;
  localparam [7:0] A_HIGH     = 8'h14;
  localparam [7:0] A_LOW      = 8'h18;
  localparam [7:0] A_EN       = 8'h1C;
  localparam [7:0] A_STAT     = 8'h20;

  reg          pclk    = 1'b0;
  reg          presetn = 1'b0;
  reg  [7:0]   paddr   = 8'h00;
  reg          psel    = 1'b0;
  reg          penable = 1'b0;
  reg          pwrite  = 1'b0;
  reg  [31:0]  pwdata  = 32'h0;
  reg  [3:0]   pstrb   = 4'h0;
  reg  [N-1:0] gpio_in = {N{1'b0}};
  wire [31:0]  prdata;
  wire         pready;
  wire         pslverr;
  wire [N-1:0] gpio_out;
  wire [N-1:0] gpio_oe;
  wire         irq;

  apb_gpio #(.ADDR_WIDTH(8), .N(N)) dut (
    .pclk     (pclk),
    .presetn  (presetn),
    .paddr    (paddr),
    .psel     (psel),
    .penable  (penable),
    .pwrite   (pwrite),
    .pwdata   (pwdata),
    .pstrb    (pstrb),
    .prdata   (prdata),
    .pready   (pready),
    .pslverr  (pslverr),
    .gpio_in  (gpio_in),
    .gpio_out (gpio_out),
    .gpio_oe  (gpio_oe),
    .irq      (irq)
  );

  always #5 pclk = ~pclk;

  integer passed = 0;
  integer failed = 0;
  reg     chk_en = 1'b0;
  reg     done   = 1'b0;
  reg [8*64-1:0] nonce;

  // ---------------------------------------------------------------------
  // Pin vectors widened to 32 bits
  // ---------------------------------------------------------------------
  reg [31:0] in_w;
  reg [31:0] out_w;
  reg [31:0] oe_w;
  integer wb;
  always @* begin
    in_w  = 32'h0;
    out_w = 32'h0;
    oe_w  = 32'h0;
    for (wb = 0; wb < N; wb = wb + 1) begin
      in_w[wb]  = gpio_in[wb];
      out_w[wb] = gpio_out[wb];
      oe_w[wb]  = gpio_oe[wb];
    end
  end

  // ---------------------------------------------------------------------
  // Reference model (written from the interface specification)
  // ---------------------------------------------------------------------
  reg [31:0] m_out;
  reg [31:0] m_dir;
  reg [31:0] m_rise;
  reg [31:0] m_fall;
  reg [31:0] m_high;
  reg [31:0] m_low;
  reg [31:0] m_en;
  reg [31:0] m_stat;
  reg [31:0] m_inq;
  reg [31:0] m_inprev;
  reg [31:0] m_mask;
  reg [31:0] m_det;
  reg [31:0] m_clr;
  reg [31:0] m_stat_nx;
  reg        m_mapped;
  reg        m_wr;
  integer    mb;

  always @* begin
    m_mapped = (paddr == A_DATA_OUT) || (paddr == A_DIR) ||
               (paddr == A_DATA_IN)  || (paddr == A_RISE) ||
               (paddr == A_FALL)     || (paddr == A_HIGH) ||
               (paddr == A_LOW)      || (paddr == A_EN) ||
               (paddr == A_STAT);
    m_wr = psel && penable && pwrite && m_mapped && (paddr != A_DATA_IN);
    for (mb = 0; mb < 32; mb = mb + 1) begin
      m_mask[mb] = pstrb[mb / 8] && (mb < N);
      m_det[mb]  = (mb < N) &&
                   ((m_rise[mb] && m_inq[mb] && !m_inprev[mb]) ||
                    (m_fall[mb] && !m_inq[mb] && m_inprev[mb]) ||
                    (m_high[mb] && m_inq[mb]) ||
                    (m_low[mb]  && !m_inq[mb]));
      m_clr[mb]  = m_wr && (paddr == A_STAT) && pwdata[mb] && m_mask[mb];
      m_stat_nx[mb] = m_det[mb] || (m_stat[mb] && !m_clr[mb]);
    end
  end

  always @(posedge pclk) begin
    if (!presetn) begin
      m_out    <= 32'h0;
      m_dir    <= 32'h0;
      m_rise   <= 32'h0;
      m_fall   <= 32'h0;
      m_high   <= 32'h0;
      m_low    <= 32'h0;
      m_en     <= 32'h0;
      m_stat   <= 32'h0;
      m_inq    <= 32'h0;
      m_inprev <= 32'h0;
    end else begin
      m_inq    <= in_w;
      m_inprev <= m_inq;
      m_stat   <= m_stat_nx;
      if (m_wr && (paddr == A_DATA_OUT)) m_out  <= (m_out  & ~m_mask) | (pwdata & m_mask);
      if (m_wr && (paddr == A_DIR))      m_dir  <= (m_dir  & ~m_mask) | (pwdata & m_mask);
      if (m_wr && (paddr == A_RISE))     m_rise <= (m_rise & ~m_mask) | (pwdata & m_mask);
      if (m_wr && (paddr == A_FALL))     m_fall <= (m_fall & ~m_mask) | (pwdata & m_mask);
      if (m_wr && (paddr == A_HIGH))     m_high <= (m_high & ~m_mask) | (pwdata & m_mask);
      if (m_wr && (paddr == A_LOW))      m_low  <= (m_low  & ~m_mask) | (pwdata & m_mask);
      if (m_wr && (paddr == A_EN))       m_en   <= (m_en   & ~m_mask) | (pwdata & m_mask);
    end
  end

  function [31:0] model_rd;
    input [7:0] ra;
    begin
      case (ra)
        A_DATA_OUT: model_rd = m_out;
        A_DIR:      model_rd = m_dir;
        A_DATA_IN:  model_rd = m_inq;
        A_RISE:     model_rd = m_rise;
        A_FALL:     model_rd = m_fall;
        A_HIGH:     model_rd = m_high;
        A_LOW:      model_rd = m_low;
        A_EN:       model_rd = m_en;
        A_STAT:     model_rd = m_stat;
        default:    model_rd = 32'h0;
      endcase
    end
  endfunction

  // ---------------------------------------------------------------------
  // Check helpers
  // ---------------------------------------------------------------------
  task check;
    input [31:0] got;
    input [31:0] ev;
    input integer id;
    begin
      if (got === ev) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got %h, expected %h", id, $time, got, ev);
      end
    end
  endtask

  task check1;
    input got;
    input ev;
    input integer id;
    begin
      if (got === ev) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got %b, expected %b", id, $time, got, ev);
      end
    end
  endtask

  // Continuous checks, 2 ns after each falling edge.
  always @(negedge pclk) begin
    #2;
    if (chk_en) begin
      check(out_w, m_out, 900);
      check(oe_w, m_dir, 901);
      check1(irq, |(m_stat & m_en), 902);
      check1(pready, 1'b1, 903);
      if (!(psel && penable)) begin
        check(prdata, 32'h0, 904);
        check1(pslverr, 1'b0, 905);
      end
    end
  end

  // ---------------------------------------------------------------------
  // APB manager tasks: called at a falling edge, return at a falling edge
  // with the bus idle (a following call starts the next setup at once).
  // ---------------------------------------------------------------------
  task apb_write;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  s;
    input        exp_err;
    input integer id;
    begin
      paddr = a; pwrite = 1'b1; pwdata = d; pstrb = s;
      psel = 1'b1; penable = 1'b0;
      #1;
      check1(pslverr, 1'b0, id);
      check(prdata, 32'h0, id);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready, 1'b1, id);
      check1(pslverr, exp_err, id);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0; pwdata = 32'h0;
    end
  endtask

  task apb_read;
    input [7:0]  a;
    input [31:0] ev;
    input        exp_err;
    input integer id;
    begin
      paddr = a; pwrite = 1'b0; pwdata = 32'h0; pstrb = 4'h0;
      psel = 1'b1; penable = 1'b0;
      #1;
      check1(pslverr, 1'b0, id);
      check(prdata, 32'h0, id);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready, 1'b1, id);
      check1(pslverr, exp_err, id);
      check(prdata, ev, id);
      check(prdata, model_rd(a), id);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0;
    end
  endtask

  task wait_neg;
    input integer n;
    begin
      repeat (n) @(negedge pclk);
    end
  endtask

  task set_pins;
    input [31:0] v;
    begin
      gpio_in = v[N-1:0];
    end
  endtask

  task chk_pins;
    input [7:0]  a;
    input [31:0] ev;
    input integer id;
    begin
      if (a == A_DATA_OUT) check(out_w, ev, id);
      if (a == A_DIR)      check(oe_w, ev, id);
    end
  endtask

  // Read/write register test: full write, partial strobes, no strobes, clear.
  task rw_test;
    input [7:0] a;
    input integer id;
    reg [31:0] e;
    begin
      apb_write(a, 32'hFFFF_FFFF, 4'hF, 1'b0, id);
      apb_read(a, PINS, 1'b0, id + 1);
      chk_pins(a, PINS, id + 2);
      apb_write(a, 32'h1234_5678, 4'b0101, 1'b0, id + 3);
      e = 32'hFF34_FF78 & PINS;
      apb_read(a, e, 1'b0, id + 4);
      chk_pins(a, e, id + 5);
      apb_write(a, 32'h0000_0000, 4'b0000, 1'b0, id + 6);
      apb_read(a, e, 1'b0, id + 7);
      apb_write(a, 32'h0000_0000, 4'b1010, 1'b0, id + 8);
      e = 32'h0034_0078 & PINS;
      apb_read(a, e, 1'b0, id + 9);
      apb_write(a, 32'h0000_0000, 4'hF, 1'b0, id + 10);
      apb_read(a, 32'h0, 1'b0, id + 11);
      chk_pins(a, 32'h0, id + 12);
    end
  endtask

  task finish_sim;
    begin
      if (!done) begin
        done = 1'b1;
        nonce = 512'd0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce[31:0] = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
      end
    end
  endtask

  // ---------------------------------------------------------------------
  // Directed sequence
  // ---------------------------------------------------------------------
  initial begin
    // T1: reset values
    presetn = 1'b0;
    repeat (3) @(negedge pclk);
    presetn = 1'b1;
    chk_en  = 1'b1;
    check(out_w, 32'h0, 100);
    check(oe_w, 32'h0, 101);
    check1(irq, 1'b0, 102);
    apb_read(A_DATA_OUT, 32'h0, 1'b0, 110);
    apb_read(A_DIR,      32'h0, 1'b0, 111);
    apb_read(A_DATA_IN,  32'h0, 1'b0, 112);
    apb_read(A_RISE,     32'h0, 1'b0, 113);
    apb_read(A_FALL,     32'h0, 1'b0, 114);
    apb_read(A_HIGH,     32'h0, 1'b0, 115);
    apb_read(A_LOW,      32'h0, 1'b0, 116);
    apb_read(A_EN,       32'h0, 1'b0, 117);
    apb_read(A_STAT,     32'h0, 1'b0, 118);

    // T2: every read/write register, partial strobes, bits above N
    rw_test(A_DATA_OUT, 200);
    rw_test(A_DIR,      220);
    rw_test(A_RISE,     240);
    rw_test(A_FALL,     260);
    rw_test(A_HIGH,     280);
    rw_test(A_LOW,      300);  // pins low: low-level sets every status bit
    rw_test(A_EN,       320);
    apb_read(A_STAT, PINS, 1'b0, 340);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0, 341);
    apb_read(A_STAT, 32'h0, 1'b0, 342);
    check1(irq, 1'b0, 343);

    // T3: PSLVERR policy, unmapped addresses, DATA_IN read only
    apb_write(A_DATA_OUT, 32'h0000_00C3, 4'hF, 1'b0, 350);
    check(out_w, 32'h0000_00C3 & PINS, 351);
    apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1, 352);  // would alias DATA_OUT
    apb_write(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1, 353);
    apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1, 354);  // unaligned
    apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1, 355);
    apb_write(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1, 356);
    apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1, 357);  // would alias DIR
    apb_read(A_DATA_OUT, 32'h0000_00C3 & PINS, 1'b0, 358);
    apb_read(A_DIR, 32'h0, 1'b0, 359);
    apb_read(8'h24, 32'h0, 1'b1, 360);
    apb_read(8'h02, 32'h0, 1'b1, 361);
    apb_read(8'h40, 32'h0, 1'b1, 362);
    apb_read(8'hE0, 32'h0, 1'b1, 363);
    apb_read(8'h3C, 32'h0, 1'b1, 364);
    apb_read(8'h23, 32'h0, 1'b1, 365);
    set_pins(32'h8001_0096);
    wait_neg(1);
    apb_read(A_DATA_IN, 32'h8001_0096 & PINS, 1'b0, 366);
    apb_write(A_DATA_IN, 32'hFFFF_FFFF, 4'hF, 1'b1, 367);
    apb_read(A_DATA_IN, 32'h8001_0096 & PINS, 1'b0, 368);
    apb_read(A_DATA_OUT, 32'h0000_00C3 & PINS, 1'b0, 369);
    apb_read(A_STAT, 32'h0, 1'b0, 370);
    set_pins(32'h0);
    wait_neg(2);

    // T4 D1: rising edge on pin 0, fires once, irq timing
    apb_write(A_EN,   32'h1, 4'hF, 1'b0, 400);
    apb_write(A_RISE, 32'h1, 4'hF, 1'b0, 401);
    set_pins(32'h1);
    @(negedge pclk);              // sampled on this edge
    check1(irq, 1'b0, 402);
    @(negedge pclk);              // status set on the next edge
    check1(irq, 1'b1, 403);
    wait_neg(3);
    apb_read(A_STAT, 32'h1, 1'b0, 404);
    apb_read(A_DATA_IN, 32'h1, 1'b0, 405);
    apb_write(A_STAT, 32'h1, 4'hF, 1'b0, 406);
    check1(irq, 1'b0, 407);
    apb_read(A_STAT, 32'h0, 1'b0, 408);
    wait_neg(3);
    apb_read(A_STAT, 32'h0, 1'b0, 409);   // edge does not fire again
    apb_write(A_EN, 32'h0, 4'hF, 1'b0, 410);

    // D2: falling edge on pin 1
    apb_write(A_FALL, 32'h2, 4'hF, 1'b0, 420);
    set_pins(32'h3);                       // rise on pin 1: not enabled
    wait_neg(3);
    apb_read(A_STAT, 32'h0, 1'b0, 421);
    set_pins(32'h1);                       // fall on pin 1
    wait_neg(2);
    apb_read(A_STAT, 32'h2, 1'b0, 422);
    apb_write(A_STAT, 32'h2, 4'hF, 1'b0, 423);
    apb_read(A_STAT, 32'h0, 1'b0, 424);

    // D3: high level on pin 2, re-sets after a clear while it holds
    apb_write(A_HIGH, 32'h4, 4'hF, 1'b0, 430);
    set_pins(32'h5);
    wait_neg(2);
    apb_read(A_STAT, 32'h4, 1'b0, 431);
    apb_write(A_STAT, 32'h4, 4'hF, 1'b0, 432);
    apb_read(A_STAT, 32'h4, 1'b0, 433);
    set_pins(32'h1);
    wait_neg(2);
    apb_write(A_STAT, 32'h4, 4'hF, 1'b0, 434);
    apb_read(A_STAT, 32'h0, 1'b0, 435);

    // D4: low level on pin 3
    apb_write(A_LOW, 32'h8, 4'hF, 1'b0, 440);
    apb_read(A_STAT, 32'h8, 1'b0, 441);
    apb_write(A_STAT, 32'h8, 4'hF, 1'b0, 442);
    apb_read(A_STAT, 32'h8, 1'b0, 443);
    set_pins(32'h9);
    wait_neg(2);
    apb_write(A_STAT, 32'h8, 4'hF, 1'b0, 444);
    apb_read(A_STAT, 32'h0, 1'b0, 445);
    apb_write(A_LOW, 32'h0, 4'hF, 1'b0, 446);

    // D5: write-1-to-clear of some pending bits only
    apb_write(A_RISE, 32'h71, 4'hF, 1'b0, 450);
    set_pins(32'h79);
    wait_neg(2);
    apb_read(A_STAT, 32'h70, 1'b0, 451);
    apb_write(A_STAT, 32'h20, 4'hF, 1'b0, 452);
    apb_read(A_STAT, 32'h50, 1'b0, 453);
    apb_write(A_STAT, 32'hFF, 4'b0000, 1'b0, 454);        // no strobes
    apb_read(A_STAT, 32'h50, 1'b0, 455);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'b1110, 1'b0, 456); // byte 0 unstrobed
    apb_read(A_STAT, 32'h50, 1'b0, 457);
    apb_write(A_STAT, 32'h0, 4'hF, 1'b0, 458);            // zeros keep
    apb_read(A_STAT, 32'h50, 1'b0, 459);
    apb_write(A_STAT, 32'h40, 4'hF, 1'b0, 460);
    apb_read(A_STAT, 32'h10, 1'b0, 461);

    // D6: interrupt mask
    check1(irq, 1'b0, 470);
    apb_write(A_EN, 32'h10, 4'hF, 1'b0, 471);
    check1(irq, 1'b1, 472);
    apb_write(A_EN, 32'h01, 4'hF, 1'b0, 473);
    check1(irq, 1'b0, 474);
    apb_write(A_STAT, 32'h10, 4'hF, 1'b0, 475);
    apb_read(A_STAT, 32'h0, 1'b0, 476);
    set_pins(32'h69);                      // fall on pin 4: not enabled
    wait_neg(3);
    set_pins(32'h79);                      // rise on pin 4 while masked
    wait_neg(2);
    apb_read(A_STAT, 32'h10, 1'b0, 477);
    check1(irq, 1'b0, 478);
    apb_write(A_EN, 32'h11, 4'hF, 1'b0, 479);
    check1(irq, 1'b1, 480);
    apb_write(A_STAT, 32'h10, 4'hF, 1'b0, 481);
    check1(irq, 1'b0, 482);
    apb_read(A_STAT, 32'h0, 1'b0, 483);
    apb_write(A_EN, 32'h0, 4'hF, 1'b0, 484);

    // D7: a detection beats a clear on the same edge (pin 5)
    set_pins(32'h59);
    wait_neg(3);
    set_pins(32'h79);
    wait_neg(2);
    apb_read(A_STAT, 32'h20, 1'b0, 490);
    set_pins(32'h59);
    wait_neg(3);
    apb_read(A_STAT, 32'h20, 1'b0, 491);
    set_pins(32'h79);                      // sampled on the setup edge,
    apb_write(A_STAT, 32'h20, 4'hF, 1'b0, 492); // detected on the clear edge
    apb_read(A_STAT, 32'h20, 1'b0, 493);
    apb_write(A_STAT, 32'h20, 4'hF, 1'b0, 494);
    apb_read(A_STAT, 32'h0, 1'b0, 495);

    // D8: both edges enabled on pin 6
    apb_write(A_FALL, 32'h42, 4'hF, 1'b0, 500);
    set_pins(32'h39);
    wait_neg(2);
    apb_read(A_STAT, 32'h40, 1'b0, 501);
    apb_write(A_STAT, 32'h40, 4'hF, 1'b0, 502);
    set_pins(32'h79);
    wait_neg(2);
    apb_read(A_STAT, 32'h40, 1'b0, 503);
    apb_write(A_STAT, 32'h40, 4'hF, 1'b0, 504);
    apb_read(A_STAT, 32'h0, 1'b0, 505);

    // T6: reset again with state everywhere
    apb_write(A_DATA_OUT, 32'hFF, 4'hF, 1'b0, 600);
    apb_write(A_DIR,      32'hF0, 4'hF, 1'b0, 601);
    apb_write(A_EN,       32'h01, 4'hF, 1'b0, 602);
    apb_write(A_HIGH,     32'h01, 4'hF, 1'b0, 603);
    wait_neg(2);
    check1(irq, 1'b1, 604);
    presetn = 1'b0;
    repeat (2) @(negedge pclk);
    presetn = 1'b1;
    check(out_w, 32'h0, 610);
    check(oe_w, 32'h0, 611);
    check1(irq, 1'b0, 612);
    apb_read(A_DATA_OUT, 32'h0, 1'b0, 613);
    apb_read(A_DIR,      32'h0, 1'b0, 614);
    apb_read(A_RISE,     32'h0, 1'b0, 615);
    apb_read(A_FALL,     32'h0, 1'b0, 616);
    apb_read(A_HIGH,     32'h0, 1'b0, 617);
    apb_read(A_LOW,      32'h0, 1'b0, 618);
    apb_read(A_EN,       32'h0, 1'b0, 619);
    apb_read(A_STAT,     32'h0, 1'b0, 620);
    apb_read(A_DATA_IN,  32'h79 & PINS, 1'b0, 621);
    wait_neg(2);

    finish_sim;
  end

  // Watchdog
  initial begin
    #1000000;
    if (!done) begin
      failed = failed + 1;
      $error("timeout: simulation did not complete");
      finish_sim;
    end
  end

endmodule

`default_nettype wire
